```python
@process.register(int)
def _(arg):
    print(f"  Integer: {arg} * 2 = {arg * 2}")

@process.register(str)
def _(arg):
    print(f"  String: '{arg}' -> '{arg.upper()}'")

@process.register(list)
def _(arg):
    print(f"  List with {len(arg)} items: sum = {sum(arg)}")

print("singledispatch in action:")
process(10)
process("hello")
process([1, 2, 3, 4, 5])
process(3.14)

print("\n" + "=" * 70)
print("All examples completed!")
print("=" * 70)
